static lstr L1290 = {0, 26427, "// std/internal/async. The loop of a thread (D109 items 6, 7 and 8): a ready\012// queue of tasks to resume, the unfinished tasks, the tasks waiting in\012// Async.idle, a timer heap and a poller (kqueue on macOS, epoll on Linux, WSAPoll on\012// Windows).\012//\012// A turn runs the ready queue in order until it is empty, then waits in the\012// poller until the nearest timer deadline or until a registered descriptor is\012// ready. When nothing is ready and nothing is waited for, the oldest idle\012// handle finishes.\012//\012// The loop waits through wait handles: bare tasks with no body (narra_wait)\012// whose value is an int64_t. A timer or descriptor wait finishes its handle\012// with 0 or more (the nanoseconds slept, or 0 when a descriptor is ready),\012// -1 when the wait was cancelled, and an errno value above 0 when the poller\012// refused the descriptor. A std function awaits the handle and turns the value\012// into its Result.\012#if defined(__APPLE__)\012#include <sys/event.h>\012#elif defined(__linux__)\012#include <sys/epoll.h>\012#elif defined(__wasi__)\012// WASI preview 1 has no descriptor poller here: the loop has timers and no\012// descriptor waits, and a turn with nothing ready sleeps until the nearest timer.\012#elif defined(_WIN32)\012#include <winsock2.h>\012#include <windows.h>\012#else\012#error \"async needs a poller: kqueue (macOS), epoll (Linux), WSAPoll (Windows) or WASI timers only\"\012#endif\012#include <errno.h>\012#include <time.h>\012\012typedef struct narra_wait narra_wait;\012struct narra_wait {\012  narra_task task;\012  int64_t value;\012  // The monotonic time the wait started, its deadline and its creation\012  // number, which orders equal deadlines.\012  int64_t started;\012  int64_t deadline;\012  int64_t sequence;\012  // Set on a wait that never finishes and that a cancel does not end: a task\012  // that waits on it again after the exit cancelled it is dropped there.\012  bool parked;\012  // The index in the timer heap, or -1.\012  int64_t slot;\012  // The descriptor it waits on, or -1, and the list of descriptor waits.\012  int descriptor;\012  bool writable;\012  narra_wait* next_io;\012  narra_wait* previous_io;\012};\012\012typedef struct narra_loop {\012  narra_task* ready_head;\012  narra_task* ready_tail;\012  narra_task* live;\012  narra_task* idle_head;\012  narra_task* idle_tail;\012  // The task whose body runs now, or NULL in a plain function.\012  narra_task* current;\012  // Set once the entry has finished: every task is cancelled from then on.\012  bool exiting;\012  // The timers: a binary min-heap by deadline, then by creation number.\012  narra_wait** timers;\012  int64_t timer_count;\012  int64_t timer_capacity;\012  int64_t timer_sequence;\012  // The descriptor waits, and the poller, opened on the first wait.\012  narra_wait* io;\012  int64_t io_count;\012  int poller;\012  bool poller_open;\012} narra_loop;\012\012static _Thread_local narra_loop narra_async_loop;\012\012#ifdef NARRA_THREADS\012static void narra_async_exit(void);\012#endif\012\012static void narra_loop_add(narra_task* task) {\012#ifdef NARRA_THREADS\012  // A thread that started a task runs the loop's exit before it ends.\012  __atomic_store_n(&narra_loop_exit_hook, narra_async_exit, __ATOMIC_RELEASE);\012#endif\012  narra_task* current = narra_async_loop.current;\012  task->cancelled = narra_async_loop.exiting;\012  task->started_cancelled = current != NULL && current->cancelled;\012  task->next_live = narra_async_loop.live;\012  task->previous_live = NULL;\012  if (narra_async_loop.live) narra_async_loop.live->previous_live = task;\012  narra_async_loop.live = task;\012}\012\012static void narra_loop_remove(narra_task* task) {\012  if (task->previous_live) {\012    task->previous_live->next_live = task->next_live;\012  } else {\012    narra_async_loop.live = task->next_live;\012  }\012  if (task->next_live) task->next_live->previous_live = task->previous_live;\012  task->next_live = NULL;\012  task->previous_live = NULL;\012}\012\012static void narra_loop_queue(narra_task* task) {\012  if (task->queued) return;\012  task->queued = true;\012  task->next_ready = NULL;\012  if (narra_async_loop.ready_tail) {\012    narra_async_loop.ready_tail->next_ready = task;\012  } else {\012    narra_async_loop.ready_head = task;\012  }\012  narra_async_loop.ready_tail = task;\012}\012\012static narra_task* narra_loop_enter(narra_task* task) {\012  narra_task* previous = narra_async_loop.current;\012  narra_async_loop.current = task;\012  return previous;\012}\012\012static void narra_loop_leave(narra_task* previous) {\012  narra_async_loop.current = previous;\012}\012\012// Resumes the ready tasks in order until none is ready.\012static void narra_loop_run_ready(void) {\012  while (narra_async_loop.ready_head) {\012    narra_task* task = narra_async_loop.ready_head;\012    narra_async_loop.ready_head = task->next_ready;\012    if (!narra_async_loop.ready_head) narra_async_loop.ready_tail = NULL;\012    task->next_ready = NULL;\012    task->queued = false;\012    narra_task* previous = narra_loop_enter(task);\012    task->resume(task);\012    narra_loop_leave(previous);\012  }\012}\012\012static void narra_task_release_nothing(narra_task* task) {\012  (void)task;\012}\012\012static int64_t narra_loop_now(void) {\012  struct timespec now;\012  clock_gettime(CLOCK_MONOTONIC, &now);\012  return (int64_t)now.tv_sec * 1000000000 + (int64_t)now.tv_nsec;\012}\012\012// The timer heap.\012\012static bool narra_timer_before(narra_wait* first, narra_wait* second) {\012  if (first->deadline != second->deadline) return first->deadline < second->deadline;\012  return first->sequence < second->sequence;\012}\012\012static void narra_timer_place(int64_t slot, narra_wait* wait) {\012  narra_async_loop.timers[slot] = wait;\012  wait->slot = slot;\012}\012\012static void narra_timer_up(int64_t slot) {\012  narra_wait* wait = narra_async_loop.timers[slot];\012  while (slot > 0) {\012    int64_t parent = (slot - 1) / 2;\012    if (!narra_timer_before(wait, narra_async_loop.timers[parent])) break;\012    narra_timer_place(slot, narra_async_loop.timers[parent]);\012    slot = parent;\012  }\012  narra_timer_place(slot, wait);\012}\012\012static void narra_timer_down(int64_t slot) {\012  narra_wait* wait = narra_async_loop.timers[slot];\012  int64_t count = narra_async_loop.timer_count;\012  while (true) {\012    int64_t child = slot * 2 + 1;\012    if (child >= count) break;\012    if (child + 1 < count && narra_timer_before(narra_async_loop.timers[child + 1], narra_async_loop.timers[child])) {\012      child++;\012    }\012    if (!narra_timer_before(narra_async_loop.timers[child], wait)) break;\012    narra_timer_place(slot, narra_async_loop.timers[child]);\012    slot = child;\012  }\012  narra_timer_place(slot, wait);\012}\012\012static void narra_timer_push(narra_wait* wait) {\012  if (narra_async_loop.timer_count == narra_async_loop.timer_capacity) {\012    int64_t capacity = narra_async_loop.timer_capacity \077 narra_async_loop.timer_capacity * 2 : 16;\012    narra_wait** timers = realloc(narra_async_loop.timers, (size_t)capacity * sizeof(narra_wait*));\012    if (!timers) {\012      fflush(stdout);\012      fprintf(stderr, \"async: out of memory for timers\\n\");\012      exit(101);\012    }\012    narra_async_loop.timers = timers;\012    narra_async_loop.timer_capacity = capacity;\012  }\012  int64_t slot = narra_async_loop.timer_count++;\012  narra_timer_place(slot, wait);\012  narra_timer_up(slot);\012}\012\012static void narra_timer_remove(narra_wait* wait) {\012  int64_t slot = wait->slot;\012  int64_t last = --narra_async_loop.timer_count;\012  wait->slot = -1;\012  if (slot == last) return;\012  // The last timer fills the hole and moves up or down to its place.\012  narra_wait* moved = narra_async_loop.timers[last];\012  narra_timer_place(slot, moved);\012  narra_timer_up(slot);\012  narra_timer_down(moved->slot);\012}\012\012// The poller.\012\012static void narra_poller_open(void) {\012#if !defined(__wasi__)\012  if (narra_async_loop.poller_open) return;\012#if defined(_WIN32)\012  // WSAPoll takes its list on every call, so there is nothing to open.\012  narra_async_loop.poller = 0;\012#elif defined(__APPLE__)\012  narra_async_loop.poller = kqueue();\012#else\012  narra_async_loop.poller = epoll_create1(0);\012#endif\012  if (narra_async_loop.poller < 0) {\012    fflush(stdout);\012    fprintf(stderr, \"async: cannot open the poller: %s\\n\", strerror(errno));\012    exit(101);\012  }\012  narra_async_loop.poller_open = true;\012#endif\012}\012\012static void narra_poller_close(void) {\012#if !defined(__wasi__)\012  if (!narra_async_loop.poller_open) return;\012#ifndef _WIN32\012  close(narra_async_loop.poller);\012#endif\012  narra_async_loop.poller_open = false;\012#endif\012}\012\012// The wait of the io list on descriptor in one direction, or NULL.\012static narra_wait* narra_io_find(int descriptor, bool writable) {\012  for (narra_wait* wait = narra_async_loop.io; wait; wait = wait->next_io) {\012    if (wait->descriptor == descriptor && wait->writable == writable) return wait;\012  }\012  return NULL;\012}\012\012static void narra_io_unlink(narra_wait* wait) {\012  if (wait->previous_io) {\012    wait->previous_io->next_io = wait->next_io;\012  } else {\012    narra_async_loop.io = wait->next_io;\012  }\012  if (wait->next_io) wait->next_io->previous_io = wait->previous_io;\012  wait->next_io = NULL;\012  wait->previous_io = NULL;\012  narra_async_loop.io_count--;\012}\012\012#if defined(__linux__)\012// epoll keeps one registration per descriptor: it watches the directions the\012// io list still waits for, and is deleted once there is none. registered is\012// true when the descriptor was in epoll before this change. 0, or the errno\012// value.\012static int narra_epoll_sync(int descriptor, bool registered) {\012  uint32_t events = 0;\012  if (narra_io_find(descriptor, false)) events |= EPOLLIN;\012  if (narra_io_find(descriptor, true)) events |= EPOLLOUT;\012  if (events == 0) {\012    if (registered) epoll_ctl(narra_async_loop.poller, EPOLL_CTL_DEL, descriptor, NULL);\012    return 0;\012  }\012  struct epoll_event event;\012  memset(&event, 0, sizeof(event));\012  event.events = events;\012  event.data.fd = descriptor;\012  int operation = registered \077 EPOLL_CTL_MOD : EPOLL_CTL_ADD;\012  if (epoll_ctl(narra_async_loop.poller, operation, descriptor, &event) < 0) return errno;\012  return 0;\012}\012#endif\012\012// Adds a wait, already in the io list, to the poller; 0, or the errno value.\012static int narra_poller_add(narra_wait* wait) {\012  narra_poller_open();\012#if defined(__wasi__)\012  (void)wait;\012  return ENOSYS;\012#elif defined(__APPLE__)\012  struct kevent change;\012  EV_SET(&change, wait->descriptor, wait->writable \077 EVFILT_WRITE : EVFILT_READ, EV_ADD | EV_ONESHOT, 0, 0, wait);\012  if (kevent(narra_async_loop.poller, &change, 1, NULL, 0, NULL) < 0) return errno;\012  return 0;\012#elif defined(_WIN32)\012  // The wait is in the io list; the next poll watches it.\012  (void)wait;\012  return 0;\012#else\012  return narra_epoll_sync(wait->descriptor, narra_io_find(wait->descriptor, !wait->writable) != NULL);\012#endif\012}\012\012// Takes a wait, already out of the io list, out of the poller. woke is true\012// when the poller reported it, so kqueue has deleted its one-shot event.\012static void narra_poller_remove(int descriptor, bool writable, bool woke) {\012#if defined(__wasi__)\012  (void)descriptor;\012  (void)writable;\012  (void)woke;\012#elif defined(__APPLE__)\012  if (woke) return;\012  struct kevent change;\012  EV_SET(&change, descriptor, writable \077 EVFILT_WRITE : EVFILT_READ, EV_DELETE, 0, 0, NULL);\012  kevent(narra_async_loop.poller, &change, 1, NULL, 0, NULL);\012#elif defined(_WIN32)\012  (void)descriptor;\012  (void)writable;\012  (void)woke;\012#else\012  (void)writable;\012  (void)woke;\012  narra_epoll_sync(descriptor, true);\012#endif\012}\012\012// Wait handles.\012\012static void narra_wait_release(narra_task* task) {\012  (void)task;\012}\012\012static narra_wait* narra_wait_new(void) {\012  narra_wait* wait = narra_alloc(sizeof(narra_wait));\012  memset(wait, 0, sizeof(narra_wait));\012  narra_task_init(&wait->task, NULL, narra_wait_release, &wait->value);\012  wait->started = narra_loop_now();\012  wait->slot = -1;\012  wait->descriptor = -1;\012  return wait;\012}\012\012static bool narra_wait_is(narra_task* task) {\012  return task->release == narra_wait_release;\012}\012\012// Marks the running task (an Async.all block) so a cancel of it stops there.\012static void narra_loop_keep_inputs(void) {\012  if (narra_async_loop.current) narra_async_loop.current->keeps_inputs = true;\012}\012\012enum { NARRA_GATE_WAIT, NARRA_GATE_CANCELLED, NARRA_GATE_PARK };\012\012static int narra_loop_gate(void) {\012  narra_task* current = narra_async_loop.current;\012  if (narra_async_loop.exiting) {\012    // A task that suspends again after the exit cancelled it is dropped there.\012    if (current == NULL) return NARRA_GATE_CANCELLED;\012    return NARRA_GATE_PARK;\012  }\012  if (current != NULL && (current->cancelled || current->started_cancelled)) return NARRA_GATE_CANCELLED;\012  return NARRA_GATE_WAIT;\012}\012\012static bool narra_loop_cancelled_now(void) {\012  return narra_loop_gate() == NARRA_GATE_CANCELLED;\012}\012\012// Takes a wait out of the heap or the poller and finishes its handle with\012// value. The handle's waiters become ready. woke is true when the poller\012// reported the descriptor.\012static void narra_wait_end(narra_wait* wait, int64_t value, bool woke) {\012  if (wait->slot >= 0) narra_timer_remove(wait);\012  if (wait->descriptor >= 0) {\012    int descriptor = wait->descriptor;\012    narra_io_unlink(wait);\012    wait->descriptor = -1;\012    narra_poller_remove(descriptor, wait->writable, woke);\012  }\012  wait->value = value;\012  narra_task_finish(&wait->task);\012}\012\012static void narra_wait_finish(narra_wait* wait, int64_t value) {\012  narra_wait_end(wait, value, false);\012}\012\012// The handle of a timer that fires after nanos (at once for zero or less,\012// after the ready tasks have run). Its value is the time slept, or -1 when\012// the running task is cancelled or is cancelled while it waits. A deadline\012// past the clock's range is the end of the range: it waits until a cancel.\012static narra_task* narra_async_sleep(int64_t nanos) {\012  narra_task* current = narra_async_loop.current;\012  if (current) current->forwards_cancel = true;\012  narra_wait* wait = narra_wait_new();\012  narra_task* handle = &wait->task;\012  int gate = narra_loop_gate();\012  if (gate == NARRA_GATE_CANCELLED) {\012    narra_wait_finish(wait, -1);\012    return handle;\012  }\012  if (gate == NARRA_GATE_PARK) {\012    wait->parked = true;\012    return handle;\012  }\012  if (nanos <= 0) {\012    wait->deadline = wait->started;\012  } else if (nanos > INT64_MAX - wait->started) {\012    wait->deadline = INT64_MAX;\012  } else {\012    wait->deadline = wait->started + nanos;\012  }\012  wait->sequence = narra_async_loop.timer_sequence++;\012  narra_timer_push(wait);\012  return handle;\012}\012\012// The handle of a wait until descriptor is ready to read, or to write when\012// writable is set. Its value is 0 when the descriptor is ready, -1 on a\012// cancel, or the errno value when the poller refuses the descriptor. One\012// reader and one writer may wait on a descriptor at once; a second wait in\012// the same direction gives EEXIST on every platform.\012static narra_task* narra_loop_wait_io(int descriptor, bool writable) {\012  narra_task* current = narra_async_loop.current;\012  if (current) current->forwards_cancel = true;\012  narra_wait* wait = narra_wait_new();\012  narra_task* handle = &wait->task;\012  int gate = narra_loop_gate();\012  if (gate == NARRA_GATE_CANCELLED) {\012    narra_wait_finish(wait, -1);\012    return handle;\012  }\012  if (gate == NARRA_GATE_PARK) {\012    wait->parked = true;\012    return handle;\012  }\012  if (narra_io_find(descriptor, writable)) {\012    narra_wait_finish(wait, EEXIST);\012    return handle;\012  }\012  wait->writable = writable;\012  wait->descriptor = descriptor;\012  wait->next_io = narra_async_loop.io;\012  if (narra_async_loop.io) narra_async_loop.io->previous_io = wait;\012  narra_async_loop.io = wait;\012  narra_async_loop.io_count++;\012  int failure = narra_poller_add(wait);\012  if (failure != 0) {\012    narra_io_unlink(wait);\012    wait->descriptor = -1;\012    narra_wait_finish(wait, failure);\012  }\012  return handle;\012}\012\012static void narra_loop_cancel_idle(narra_task* idle);\012\012// A cancel of task passes down the await chain (D109 item 8, amended\012// 2026-11-13) to the wait at its end: an Async.idle handle, which finishes,\012// or a timer or descriptor wait, which finishes with -1. The task of a\012// suspending std function passes it on. A user task it awaits is cancelled\012// too when the waiter is the only task waiting on it, it has no then\012// callbacks and no unfinished Async.all was given it; a handle that other\012// tasks await, that has callbacks or that an Async.all observes keeps\012// running, and so do the tasks a cancelled task started but does not await.\012// The race watchers wait on every handle of an undecided Async.race, so its\012// handles are never alone. The task of Async.all stops the walk, as the\012// winner of Async.race does, so neither cancels the handles it was given. Async.cancel calls this after it\012// sets the cancelled flag, and so does an await in a task that is already\012// cancelled.\012static void narra_loop_cancel_wait(narra_task* task) {\012  narra_task* waiter = task;\012  narra_task* awaited = task->awaited;\012  while (awaited && !awaited->done && !waiter->keeps_inputs) {\012    if (waiter->is_step) {\012      // A pending step passes the cancel to its stream when it is the\012      // stream's only pending step (D110 item 4).\012      narra_stream* stream = (narra_stream*)awaited;\012      narra_step* step = (narra_step*)waiter;\012      bool only = stream->s.first_step == step && step->next_step == NULL;\012      if (!only || !narra_task_mark_cancelled(awaited)) return;\012      waiter = awaited;\012      awaited = awaited->awaited;\012      continue;\012    }\012    if (awaited->release == narra_task_release_nothing) {\012      narra_loop_cancel_idle(awaited);\012      return;\012    }\012    if (narra_wait_is(awaited)) {\012      if (((narra_wait*)awaited)->parked) return;\012      narra_wait_finish((narra_wait*)awaited, -1);\012      return;\012    }\012    if (!awaited->forwards_cancel) {\012      // A bare task (a race winner) has no wait of its own to end; a step\012      // passes the cancel on to its stream.\012      if (awaited->resume == NULL && !awaited->is_step) return;\012      bool alone = awaited->waiters == waiter && waiter->next_waiter == NULL;\012      if (!alone || awaited->callbacks != NULL || awaited->observers != 0) return;\012      if (!narra_task_mark_cancelled(awaited)) return;\012    }\012    waiter = awaited;\012    awaited = awaited->awaited;\012  }\012}\012\012// Finishes every timer and descriptor wait with -1 (at exit).\012static void narra_loop_cancel_all_waits(void) {\012  while (narra_async_loop.timer_count > 0) {\012    narra_wait_finish(narra_async_loop.timers[0], -1);\012  }\012  while (narra_async_loop.io) {\012    narra_wait_finish(narra_async_loop.io, -1);\012  }\012}\012\012// The longest single wait in the poller, one day; the loop waits again after it.\012#define NARRA_POLL_LIMIT ((int64_t)86400 * 1000000000)\012\012// A poller error other than a signal is a broken loop: stop as a panic does\012// rather than spin.\012static void narra_poller_failed(void) {\012  fflush(stdout);\012#ifdef _WIN32\012  fprintf(stderr, \"async: the poller failed: Winsock error %d\\n\", WSAGetLastError());\012#else\012  fprintf(stderr, \"async: the poller failed: %s\\n\", strerror(errno));\012#endif\012  exit(101);\012}\012\012#ifdef _WIN32\012// Waits up to timeout nanoseconds for the sockets of the io list, one entry\012// per wait; with none, the thread sleeps until the nearest timer. A closed or\012// failed socket wakes its wait too, as with epoll.\012static void narra_poll_sockets(int64_t timeout) {\012  int64_t milliseconds = (timeout + 999999) / 1000000;\012  if (narra_async_loop.io_count == 0) {\012    Sleep((DWORD)milliseconds);\012    return;\012  }\012  int64_t total = narra_async_loop.io_count;\012  WSAPOLLFD* entries = malloc((size_t)total * sizeof(WSAPOLLFD));\012  narra_wait** waiting = malloc((size_t)total * sizeof(narra_wait*));\012  if (!entries || !waiting) {\012    fflush(stdout);\012    fprintf(stderr, \"async: out of memory for the poller\\n\");\012    exit(101);\012  }\012  int64_t listed = 0;\012  for (narra_wait* wait = narra_async_loop.io; wait; wait = wait->next_io) {\012    entries[listed].fd = (SOCKET)wait->descriptor;\012    entries[listed].events = wait->writable \077 POLLWRNORM : POLLRDNORM;\012    entries[listed].revents = 0;\012    waiting[listed] = wait;\012    listed++;\012  }\012  int ready = WSAPoll(entries, (ULONG)listed, (INT)milliseconds);\012  if (ready == SOCKET_ERROR) narra_poller_failed();\012  for (int64_t i = 0; ready > 0 && i < listed; i++) {\012    if (entries[i].revents != 0) narra_wait_end(waiting[i], 0, true);\012  }\012  free(entries);\012  free(waiting);\012}\012#endif\012\012// Waits in the poller until the nearest deadline (at most a day) or a ready\012// descriptor, then finishes the waits that are due. False when there is\012// nothing to wait for.\012static bool narra_loop_poll(void) {\012  if (narra_async_loop.timer_count == 0 && narra_async_loop.io_count == 0) return false;\012  narra_poller_open();\012  int64_t timeout = NARRA_POLL_LIMIT;\012  if (narra_async_loop.timer_count > 0) {\012    int64_t deadline = narra_async_loop.timers[0]->deadline;\012    int64_t now = narra_loop_now();\012    int64_t left = deadline <= now \077 0 : deadline - now;\012    if (left < timeout) timeout = left;\012  }\012#if defined(__wasi__)\012  // Only timers exist: sleep until the nearest deadline.\012  struct timespec limit;\012  limit.tv_sec = (time_t)(timeout / 1000000000);\012  limit.tv_nsec = (long)(timeout % 1000000000);\012  nanosleep(&limit, NULL);\012#elif defined(_WIN32)\012  narra_poll_sockets(timeout);\012#else\012  enum { NARRA_POLL_EVENTS = 64 };\012  int count;\012#if defined(__APPLE__)\012  struct kevent events[NARRA_POLL_EVENTS];\012  struct timespec limit;\012  limit.tv_sec = (time_t)(timeout / 1000000000);\012  limit.tv_nsec = (long)(timeout % 1000000000);\012  count = kevent(narra_async_loop.poller, NULL, 0, events, NARRA_POLL_EVENTS, &limit);\012#else\012  struct epoll_event events[NARRA_POLL_EVENTS];\012  // epoll waits in milliseconds: round up, so a timer is never woken early.\012  int milliseconds = (int)((timeout + 999999) / 1000000);\012  count = epoll_wait(narra_async_loop.poller, events, NARRA_POLL_EVENTS, milliseconds);\012#endif\012  if (count < 0) {\012    if (errno != EINTR) narra_poller_failed();\012    count = 0;\012  }\012  for (int i = 0; i < count; i++) {\012#if defined(__APPLE__)\012    narra_wait_end(events[i].udata, 0, true);\012#else\012    // One event per descriptor: wake the reader and the writer it reports.\012    int descriptor = events[i].data.fd;\012    uint32_t ready = events[i].events;\012    uint32_t broken = EPOLLERR | EPOLLHUP;\012    narra_wait* reader = narra_io_find(descriptor, false);\012    narra_wait* writer = narra_io_find(descriptor, true);\012    if (reader && (ready & (EPOLLIN | broken))) narra_wait_end(reader, 0, true);\012    if (writer && (ready & (EPOLLOUT | broken))) narra_wait_end(writer, 0, true);\012#endif\012  }\012#endif\012  int64_t now = narra_loop_now();\012  while (narra_async_loop.timer_count > 0 && narra_async_loop.timers[0]->deadline <= now) {\012    narra_wait* wait = narra_async_loop.timers[0];\012    narra_wait_finish(wait, now - wait->started);\012  }\012  return true;\012}\012\012// Async.idle: a handle that finishes once no other task can run: nothing is\012// ready, no timer is set and no descriptor is waited on. Idle handles finish\012// one at a time in the order they were made, so a task started by an earlier\012// one counts for the later ones. In a cancelled task it finishes at once. At\012// exit it wakes the task once; the next idle of that task drops it.\012static narra_task* narra_async_idle(void) {\012  narra_task* task = narra_alloc(sizeof(narra_task));\012  memset(task, 0, sizeof(narra_task));\012  narra_task_init(task, NULL, narra_task_release_nothing, NULL);\012  narra_task* current = narra_async_loop.current;\012  if (narra_async_loop.exiting && narra_loop_gate() == NARRA_GATE_PARK) return task;\012  if (task->cancelled || (current && current->cancelled)) {\012    narra_task_finish(task);\012    return task;\012  }\012  if (narra_async_loop.idle_tail) {\012    narra_async_loop.idle_tail->next_ready = task;\012  } else {\012    narra_async_loop.idle_head = task;\012  }\012  narra_async_loop.idle_tail = task;\012  return task;\012}\012\012// Takes an idle handle out of the idle list and finishes it (a cancel of the\012// task that waits in it).\012static void narra_loop_cancel_idle(narra_task* idle) {\012  narra_task* previous = NULL;\012  for (narra_task* task = narra_async_loop.idle_head; task; task = task->next_ready) {\012    if (task != idle) {\012      previous = task;\012      continue;\012    }\012    if (previous) {\012      previous->next_ready = task->next_ready;\012    } else {\012      narra_async_loop.idle_head = task->next_ready;\012    }\012    if (narra_async_loop.idle_tail == task) narra_async_loop.idle_tail = previous;\012    task->next_ready = NULL;\012    narra_task_finish(task);\012    return;\012  }\012}\012\012// Finishes the oldest idle handle; false when there is none.\012static bool narra_loop_wake_idle(void) {\012  narra_task* task = narra_async_loop.idle_head;\012  if (!task) return false;\012  narra_async_loop.idle_head = task->next_ready;\012  if (!narra_async_loop.idle_head) narra_async_loop.idle_tail = NULL;\012  task->next_ready = NULL;\012  narra_task_finish(task);\012  return true;\012}\012\012// Runs the loop until the entry's handle is done and gives its value, the\012// exit code. Nothing ready, no timer, no descriptor and no idle handle while\012// the entry waits means the tasks wait on each other: the program stops as a\012// panic does.\012static int64_t narra_async_run_entry(narra_task* entry) {\012  while (!entry->done) {\012    narra_loop_run_ready();\012    if (entry->done) break;\012    if (narra_loop_poll()) continue;\012    if (narra_loop_wake_idle()) continue;\012    fflush(stdout);\012    fprintf(stderr, \"async: every task waits on another task\\n\");\012    exit(101);\012  }\012  int64_t code = *(int64_t*)entry->value;\012  narra_task_release(entry);\012  return code;\012}\012\012// The exit of D95: every unfinished task is cancelled, every timer and\012// descriptor wait finishes with -1, and the loop runs until nothing is ready.\012// A task still waiting then waits on a handle that cannot finish; its frame\012// releases what it holds, and the loop drops it. Releasing every frame before\012// dropping any breaks the cycles through those frames. Last, the poller\012// closes.\012static void narra_async_exit(void) {\012  narra_task_check_watchers(narra_async_loop.live);\012  narra_async_loop.exiting = true;\012  for (narra_task* task = narra_async_loop.live; task; task = task->next_live) {\012    narra_task_mark_cancelled(task);\012  }\012  do {\012    narra_loop_cancel_all_waits();\012    narra_loop_run_ready();\012  } while (narra_loop_wake_idle());\012  for (narra_task* task = narra_async_loop.live; task; task = task->next_live) {\012    task->release(task);\012    task->dropped = true;\012  }\012  for (narra_task* task = narra_async_loop.live; task; task = task->next_live) {\012    while (task->waiters) {\012      narra_task* waiter = task->waiters;\012      task->waiters = waiter->next_waiter;\012      waiter->next_waiter = NULL;\012      waiter->awaited = NULL;\012      narra_task_release(waiter);\012    }\012  }\012  while (narra_async_loop.live) {\012    narra_task* task = narra_async_loop.live;\012    narra_loop_remove(task);\012    narra_task_release(task);\012  }\012  free(narra_async_loop.timers);\012  narra_async_loop.timers = NULL;\012  narra_async_loop.timer_capacity = 0;\012  narra_poller_close();\012}\012"};
