static lstr L1296 = {0, 857, "// std/internal/clock. The monotonic clock, the wall clock and sleep.\012#include <errno.h>\012#include <time.h>\012\012static int64_t narra_clock_monotonic_nanos(void) {\012  struct timespec now;\012  clock_gettime(CLOCK_MONOTONIC, &now);\012  return (int64_t)now.tv_sec * 1000000000 + (int64_t)now.tv_nsec;\012}\012\012static int64_t narra_clock_wall_millis(void) {\012  struct timespec now;\012  clock_gettime(CLOCK_REALTIME, &now);\012  return (int64_t)now.tv_sec * 1000 + (int64_t)now.tv_nsec / 1000000;\012}\012\012// Sleeps for the given nanoseconds, again after a signal; a value of zero or less returns at once.\012static void narra_clock_sleep_nanos(int64_t nanos) {\012  if (nanos <= 0) return;\012  struct timespec remaining;\012  remaining.tv_sec = (time_t)(nanos / 1000000000);\012  remaining.tv_nsec = (long)(nanos % 1000000000);\012  while (nanosleep(&remaining, &remaining) != 0 && errno == EINTR) {\012  }\012}\012"};
